const $=s=>document.querySelector(s),A=RepoAccount,P=RepoProviders,S=RepoStore,Q=RepoQuality,E=RepoEditorial;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let rows=[],repos=[],repoMap=new Map(),editing=null,selected=[],started=false,busy=false,builtinSetupRequired=false,activeTab=['editorial','analytics','sync','users','help'].includes(new URL(location.href).searchParams.get('tab'))?new URL(location.href).searchParams.get('tab'):'editorial';
let users=[],userCursor=null,userToken=0,userSearchTimer;let projectToken=0,projectTimer,projectCursor=null;
const message=(text,error=false)=>{$('#admin-message').textContent=text;$('#admin-message').classList.toggle('error',error)};
function gate(){if(!A.ready)return;if(!A.user?.admin){analyticsToken++;syncToken++;userToken++;started=false;projectToken++;repoMap.clear();repos=[];$('#analytics-content').innerHTML='';rows=[];editing=null;selected=[];users=[];$('#users-content').innerHTML='';$('#sync-content').innerHTML='';$('#help-content').innerHTML='';$('#admin-workspace').hidden=true;$('#admin-gate').hidden=false;$('#admin-gate').innerHTML=`<p class="eyebrow">ADMINISTRATION</p><h1>${A.user?'Administrator access required':A.enabled?'Sign in to your workspace':'Administration is being set up'}</h1><p>${A.user?'Your account can save likes. Storefront editing and analytics require an administrator role.':A.enabled?'Use the GitHub account that has been granted administrator access.':'The storefront is available while account setup is completed.'}</p>${!A.user&&A.enabled?'<a class="button lime" href="/api/auth?action=start&return=%2Fadmin.html">Sign in with GitHub ↗</a>':''}<a class="button outline" href="/">Back to the store</a>`;return}$('#admin-gate').hidden=true;$('#admin-workspace').hidden=false;if(!started){started=true;void initialize();activateTab(activeTab)}}
async function initialize(){message('Loading your workspace…');try{const [data,browse]=await Promise.all([A.request('/api/editorial?manage=1'),A.request('/api/editorial?action=browse&manage=1',{method:'POST',body:JSON.stringify({demos:false,limit:30})})]);builtinSetupRequired=data.builtinSetupRequired===true;if(!A.user?.admin)return;rows=E.resolve(data.rows);$('#editorial-setup').hidden=!builtinSetupRequired;$('#editorial-setup').innerHTML='Apply <a href="https://github.com/sparx1981/RepoShelf/blob/main/supabase/migrations/202610040008_editorial_discovery_qa.sql" target="_blank" rel="noopener">migration 8</a> in Supabase to edit built-in rows and enable random ordering. Existing custom rows remain available.';repos=browse.items;repoMap=new Map(repos.map(r=>[r.full,r]));$('#custom-rows').checked=data.customRows;$('#row-category').innerHTML='<option value="">Any category</option>'+Object.keys(browse.facets.categories).sort().map(x=>`<option>${esc(x)}</option>`).join('');renderRows();reset();message('')}catch(e){message(e.message,true)}}
async function reload(){const data=await A.request('/api/editorial?manage=1');builtinSetupRequired=data.builtinSetupRequired===true;if(!A.user?.admin)return;rows=E.resolve(data.rows);$('#editorial-setup').hidden=!builtinSetupRequired;$('#editorial-setup').innerHTML='Apply <a href="https://github.com/sparx1981/RepoShelf/blob/main/supabase/migrations/202610040008_editorial_discovery_qa.sql" target="_blank" rel="noopener">migration 8</a> in Supabase to edit built-in rows and enable random ordering. Existing custom rows remain available.';$('#custom-rows').checked=data.customRows;renderRows()}
function renderRows(){const movable=rows.filter(r=>!builtinSetupRequired||!r.builtin_key);$('#row-list').innerHTML=rows.length?rows.map(row=>{const i=movable.findIndex(r=>r.id===row.id),locked=builtinSetupRequired&&row.builtin_key;return `<article class="row-tile"><h3>${esc(row.title)}</h3><p>${row.builtin_key?'Built-in · ':''}${row.enabled?'Published':'Draft'} · ${row.mode==='manual'?`${row.items.length} selected projects`:esc(E.modes[row.mode]||row.mode)}${row.category?' · '+esc(row.category):''}</p><div class="row-tile-actions"><button data-edit="${row.id}">Edit</button><button data-move="${row.id}" data-step="-1" aria-label="Move ${esc(row.title)} up" ${locked||i<=0?'disabled':''}>↑</button><button data-move="${row.id}" data-step="1" aria-label="Move ${esc(row.title)} down" ${locked||i===movable.length-1?'disabled':''}>↓</button><button data-publish="${row.id}" ${locked?'disabled':''}>${row.enabled?'Unpublish':'Publish'}</button>${row.builtin_key?'':`<button data-delete="${row.id}">Delete</button>`}</div></article>`}).join(''):'<p class="small">Create your first category row. Start with a draft and publish when it is ready.</p>'}
function reset(){editing=null;selected=[];$('#row-form').reset();$('#editor-title').textContent='Create a row';$('#row-state').textContent='Draft';renderSelection();searchProjects();updateMode()}
function edit(row){editing={...row};selected=[...row.items];$('#editor-title').textContent='Edit row';$('#row-title').value=row.title;$('#row-description').value=row.description;$('#row-category').value=row.category;$('#row-mode').value=row.mode;$('#row-enabled').checked=row.enabled;$('#row-state').textContent=row.enabled?'Published':'Draft';renderSelection();void hydrateSelection(selected);void searchProjects();updateMode();$('#row-title').focus()}
function values(){return {builtin_key:editing?.builtin_key,id:editing?.id,revision:editing?.revision,title:$('#row-title').value,description:$('#row-description').value,category:$('#row-category').value,mode:$('#row-mode').value,enabled:$('#row-enabled').checked,items:selected}}
function renderSelection(){$('#selection-count').textContent=`${selected.length} selected` ;$('#selected-projects').innerHTML=selected.length?selected.map((id,i)=>`<div class="selected-project"><span>${esc(repoMap.get(id)?.name||id)}<small>${esc(id)}${!repoMap.has(id)?' · Details not loaded':''}</small></span><button data-selected-move="${i}" data-step="-1" aria-label="Move ${esc(id)} up" ${i===0?'disabled':''}>↑</button><button data-selected-move="${i}" data-step="1" aria-label="Move ${esc(id)} down" ${i===selected.length-1?'disabled':''}>↓</button><button data-remove="${i}" aria-label="Remove ${esc(id)}">×</button></div>`).join(''):'<p class="small">Choose the projects that belong on this shelf.</p>'}
async function searchProjects(append=false){const token=++projectToken;if(!append)projectCursor=null;try{const data=await A.request('/api/editorial?action=browse&manage=1',{method:'POST',body:JSON.stringify({q:$('#project-search').value,category:$('#row-category').value,demos:false,limit:30,cursor:append?projectCursor:null})});if(token!==projectToken||!A.user?.admin)return;repos=append?[...repos,...data.items]:data.items;projectCursor=data.nextCursor;for(const r of data.items)repoMap.set(r.full,r);$('#project-results').innerHTML=repos.map(r=>`<button type="button" class="project-choice" data-select="${esc(r.full)}" ${selected.includes(r.full)?'disabled':''}><strong>${esc(r.name)}</strong><small>${esc(r.category)} · ${esc(r.full)}${Q.hasLiveDemo(r)?' · Demo':''}</small></button>`).join('')||'<p class="small">No matching projects.</p>';if(projectCursor)$('#project-results').insertAdjacentHTML('beforeend','<button type="button" class="button outline" data-more-projects>Show more projects</button>');renderSelection()}catch(e){if(token===projectToken&&A.user?.admin)message(e.message,true)}}
async function hydrateSelection(ids){await Promise.all(ids.filter(id=>!repoMap.has(id)).map(async id=>{try{const data=await A.request('/api/editorial?action=detail&id='+encodeURIComponent(id));if(A.user?.admin)repoMap.set(id,data.repo)}catch{}}));if(A.user?.admin)renderSelection()}

function updateMode(){const manual=$('#row-mode').value==='manual';const mode=$('#row-mode').value;$('#automatic-note').textContent=mode==='random'?'A fresh order is chosen for each page load and stays stable while browsing.':mode==='daily'?'A consistent daily order is shared by visitors, changing at midnight UTC.':'Projects are selected automatically from the chosen category. Live-demo and technology filters still apply.';$('#manual-selection').hidden=!manual;$('#automatic-note').hidden=manual}
async function task(fn){if(busy)return;busy=true;$('#save-row').disabled=true;try{await fn()}catch(e){message(e.message,true);if(e.status===409)await reload();if(e.status===401||e.status===403)await A.refresh()}finally{busy=false;$('#save-row').disabled=false}}
$('#row-form').onsubmit=e=>{e.preventDefault();void task(async()=>{if(builtinSetupRequired&&(editing?.builtin_key||['random','daily','community','releases'].includes($('#row-mode').value))){message('Apply migration 8 in Supabase, then refresh this page to save these settings.',true);return}message('Saving row…');const data=await A.request('/api/editorial',{method:'POST',body:JSON.stringify({row:values()})});await reload();edit(data.row);message(data.row.enabled?'Published. The row is available on the storefront.':'Draft saved.')})};
$('#new-row').onclick=reset;$('#reset-row').onclick=reset;$('#project-search').oninput=()=>{clearTimeout(projectTimer);projectTimer=setTimeout(()=>void searchProjects(),250)};$('#row-category').onchange=searchProjects;$('#row-mode').onchange=updateMode;$('#row-enabled').onchange=()=>$('#row-state').textContent=$('#row-enabled').checked?'Ready to publish':'Draft';
$('#custom-rows').onchange=e=>void task(async()=>{await A.request('/api/editorial',{method:'POST',body:JSON.stringify({action:'settings',customRows:e.target.checked})});message(e.target.checked?'Custom rows enabled; built-in feature ribbons remain editable.':'Built-in category rows restored.')});
