document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-more-projects')){void searchProjects(true);return}if(b.dataset.adminTab){activateTab(b.dataset.adminTab);return}if(b.dataset.roleUser){void changeRole(b.dataset.roleUser);return}if(b.dataset.select){if(selected.length>=120){message('This row can contain up to 120 selected projects.',true);return}selected.push(b.dataset.select);renderSelection();searchProjects();return}if(b.dataset.remove!==undefined){selected.splice(Number(b.dataset.remove),1);renderSelection();searchProjects();return}if(b.dataset.selectedMove!==undefined){const i=Number(b.dataset.selectedMove),j=i+Number(b.dataset.step);[selected[i],selected[j]]=[selected[j],selected[i]];renderSelection();return}if(b.dataset.edit){edit(rows.find(r=>r.id===b.dataset.edit));return}if(b.dataset.move)void task(async()=>{const movable=rows.filter(r=>!builtinSetupRequired||!r.builtin_key),i=movable.findIndex(r=>r.id===b.dataset.move),j=i+Number(b.dataset.step),ids=movable.map(r=>r.id);if(i<0||j<0||j>=ids.length)return;[ids[i],ids[j]]=[ids[j],ids[i]];await A.request('/api/editorial',{method:'POST',body:JSON.stringify({action:'reorder',ids})});await reload();if(editing)editing={...rows.find(r=>r.id===editing.id)};message('Row order updated.')});if(b.dataset.publish)void task(async()=>{const row=rows.find(r=>r.id===b.dataset.publish);await A.request('/api/editorial',{method:'POST',body:JSON.stringify({row:{...row,enabled:!row.enabled}})});await reload();message(row.enabled?'Row unpublished.':'Row published.')});if(b.dataset.delete){const row=rows.find(r=>r.id===b.dataset.delete);if(confirm(`Delete the “${row.title}” row? Projects remain in the catalog.`))void task(async()=>{await A.request('/api/editorial',{method:'DELETE',body:JSON.stringify({id:row.id,revision:row.revision})});if(editing?.id===row.id)reset();await reload();message('Row deleted.')})}});
function metric(value,label){return `<div class="metric"><strong>${value===null?'—':Number(value||0).toLocaleString()}</strong><span>${esc(label)}</span></div>`}
function chart(data,key,label){if(!data.length)return '<p class="chart-empty">History will appear as refreshes complete.</p>';const values=data.map(r=>Number(r[key]||0)),min=Math.min(...values),max=Math.max(...values),range=max-min||1;const points=values.map((v,i)=>`${20+i/Math.max(1,values.length-1)*660},${145-(v-min)/range*115}`).join(' ');return `<svg viewBox="0 0 700 175" role="img" aria-label="${esc(label)}: ${values[0]} to ${values.at(-1)}"><path d="M20 145H680" stroke="#3a482f"/><polyline fill="none" stroke="#c6ec88" stroke-width="3" stroke-linejoin="round" points="${points}"/>${data.map((r,i)=>`<circle cx="${20+i/Math.max(1,values.length-1)*660}" cy="${145-(values[i]-min)/range*115}" r="4" fill="#c6ec88"><title>${esc(r.day||r.at)}: ${values[i].toLocaleString()}</title></circle>`).join('')}</svg><div class="chart-axis"><span>${esc((data[0].day||data[0].at).slice(0,10))}</span><span>${esc((data.at(-1).day||data.at(-1).at).slice(0,10))}</span></div>`}
let analyticsToken=0;
async function loadAnalytics(){const token=++analyticsToken;$('#analytics-content').innerHTML='<p class="loading-note">Loading activity…</p>';try{const days=Number($('#analytics-range').value),data=await A.request('/api/analytics?days='+days);if(token!==analyticsToken||!A.user?.admin)return;const daily=data.daily||[],total=key=>daily.reduce((n,r)=>n+Number(r[key]||0),0);const cutoff=Date.parse(new Date().toISOString().slice(0,10)+'T00:00:00Z')-(days-1)*86400000,growth=(data.growth||[]).filter(r=>Date.parse(r.at)>=cutoff);$('#analytics-content').innerHTML=`${!data.trackingEnabled?'<p class="analytics-caption">Visit tracking is awaiting activation. Catalog coverage is available below.</p>':''}<div class="metric-grid">${metric(data.uniqueVisitors??null,'Unique visitors')}${metric(total('visits'),'Visits')}${metric(total('page_views'),'Page views')}${metric(total('listing_views'),'Listing views')}${metric(total('demo_clicks'),'Demo clicks')}${metric(total('fork_clicks'),'Fork / duplicate clicks')}${metric(total('searches'),'Searches')}${metric(data.totalLikes,'Current saved likes')}${metric(data.likesAdded,'Likes added and still saved')}</div><div class="analytics-grid"><section class="analytics-box"><h3>Page views over time</h3>${chart(daily,'page_views','Page views')}<p class="analytics-caption">${esc(data.visitorMethod)}</p><p class="analytics-caption">${data.uniqueVisitorsSince?'Unique visitor tracking started '+esc(new Date(data.uniqueVisitorsSince).toLocaleString())+'. Earlier visits are excluded from this stat.':'Apply <a href="https://github.com/sparx1981/RepoShelf/blob/main/supabase/migrations/202610030003_unique_visitors.sql" target="_blank" rel="noopener noreferrer">migration 3</a> in Supabase to activate this stat. Existing visit totals remain available.'}</p><details><summary>Daily counts</summary><table class="analytics-table"><thead><tr><th>Date (UTC)</th><th>Visits</th><th>Views</th><th>Visitors</th></tr></thead><tbody>${daily.map(r=>`<tr><td>${r.day}</td><td>${r.visits}</td><td>${r.page_views}</td><td>${r.visitors}</td></tr>`).join('')}</tbody></table></details></section><section class="analytics-box"><h3>Most viewed projects</h3>${data.topListings?.length?`<table class="analytics-table"><thead><tr><th>Project</th><th>Views</th></tr></thead><tbody>${data.topListings.map(r=>`<tr><td>${esc(repoMap.get(r.project_id)?.name||r.project_id)}</td><td>${Number(r.views).toLocaleString()}</td></tr>`).join('')}</tbody></table>`:'<p class="chart-empty">Listing views will appear here.</p>'}</section></div><section class="analytics-box"><h3>Library growth</h3><div class="metric-grid">${metric(data.coverage.availableProjects,'Available projects')}${metric(data.coverage.withDemo,'With demos')}${metric(data.coverage.readmesSaved,'Saved READMEs')}${metric(data.coverage.supportingContextsSaved,'Supporting contexts')}</div>${chart(growth,'records','Indexed projects')}<details><summary>Catalog snapshots</summary><table class="analytics-table"><thead><tr><th>Date (UTC)</th><th>Projects</th><th>Demos</th><th>Previews</th><th>Unavailable</th></tr></thead><tbody>${growth.slice(-30).map(r=>`<tr><td>${esc(r.at.slice(0,16).replace('T',' '))}</td><td>${r.records}</td><td>${r.withDemo}</td><td>${r.withScreenshot}</td><td>${r.unavailable}</td></tr>`).join('')}</tbody></table></details><p class="analytics-caption">Growth history starts with this update and is saved after each catalog refresh. Fork clicks represent intent, not a confirmed fork. No search text or IP addresses are stored. Daily totals remain; detailed activity is retained for 90 days.</p></section>`}catch(e){if(token===analyticsToken&&A.user?.admin)$('#analytics-content').innerHTML=`<p class="loading-note">${esc(e.message)}</p>`;if(e.status===401||e.status===403)await A.refresh()}}
$('#analytics-range').onchange=()=>void loadAnalytics();window.addEventListener('reposhelf-account',gate);

function activateTab(tab){if(!['editorial','analytics','sync','users','help'].includes(tab)||!A.user?.admin)return;activeTab=tab;for(const name of ['editorial','analytics','sync','users','help'])$('#'+name+'-panel').hidden=name!==tab;document.querySelectorAll('.admin-tabs [data-admin-tab]').forEach(button=>button.classList.toggle('active',button.dataset.adminTab===tab));history.replaceState(null,'','/admin.html'+(tab==='editorial'?'':'?tab='+tab));message('');if(tab==='sync')void loadSyncLog();if(tab==='analytics')void loadAnalytics();if(tab==='users')void loadUsers();if(tab==='help')void loadHelp()}
function renderUsers(){$('#users-content').innerHTML=users.length?`<div class="help-table-wrap"><table class="analytics-table users-table"><thead><tr><th>User</th><th>Role</th><th>Last sign-in</th><th>Access</th></tr></thead><tbody>${users.map(person=>`<tr><td><strong>${esc(person.username==='GitHub user'?person.username:'@'+person.username)}${person.id===A.user?.id?' · You':''}</strong><small>GitHub ID: ${esc(person.github_id)}</small><small>${esc(person.id)}</small></td><td><span class="status-pill">${person.admin?'Administrator':'Member'}</span></td><td>${esc(new Date(person.last_sign_in_at).toLocaleDateString())}</td><td>${person.id===A.user?.id?'<span class="small">Your role is protected</span>':`<button class="button ${person.admin?'outline':'lime'}" data-role-user="${person.id}" ${busy?'disabled':''}>${person.admin?'Remove admin':'Grant admin'}</button>`}</td></tr>`).join('')}</tbody></table></div>`:'<p class="chart-empty">No signed-in users match this search.</p>';$('#more-users').hidden=!userCursor}
async function loadUsers(append=false){const token=++userToken,q=$('#user-search').value.trim();if(!append){users=[];userCursor=null;$('#users-content').innerHTML='<p class="loading-note">Loading users…</p>';$('#more-users').hidden=true}try{const params=new URLSearchParams({q});if(append&&userCursor)params.set('cursor',userCursor);const data=await A.request('/api/admin-users?'+params);if(token!==userToken||!A.user?.admin)return;users=append?[...users,...data.items]:data.items;userCursor=data.nextCursor;renderUsers()}catch(e){if(token===userToken)$('#users-content').innerHTML=`<p class="loading-note">${esc(e.message)}</p><button class="button outline" data-admin-tab="help">Open Help</button>`;if(e.status===401||e.status===403)await A.refresh()}}
async function changeRole(id){const person=users.find(u=>u.id===id);if(!person||busy)return;const makeAdmin=!person.admin;if(!confirm(`${makeAdmin?'Grant administrator access to':'Remove administrator access from'} @${person.username} (GitHub ID ${person.github_id})?${makeAdmin?' They will be able to edit the store, view analytics and manage roles.':''}`))return;await task(async()=>{renderUsers();try{await A.request('/api/admin-users',{method:'PUT',body:JSON.stringify({id,admin:makeAdmin,expectedAdmin:person.admin})})}catch(e){if(e.status===409)await loadUsers();throw e}await loadUsers();message(makeAdmin?'Administrator access granted. The user can reload to see the admin menu.':'Administrator access removed.')});renderUsers()}
async function loadHelp(){$('#help-content').innerHTML='<p class="loading-note">Checking connection settings…</p>';try{const setup=await A.request('/api/admin-users?action=setup');if(!A.user?.admin)return;$('#help-content').innerHTML=RepoAdminHelp.render(setup)}catch(e){$('#help-content').innerHTML=`<p class="loading-note">${esc(e.message)}</p>`;if(e.status===401||e.status===403)await A.refresh()}}
$('#user-search').oninput=()=>{clearTimeout(userSearchTimer);userSearchTimer=setTimeout(()=>void loadUsers(),300)};$('#more-users').onclick=()=>void loadUsers(true);


let syncPage=1,syncToken=0;
async function loadSyncLog(){const token=++syncToken;$('#sync-content').innerHTML='<p class="loading-note">Loading sync history…</p>';try{const data=await A.request('/api/sync-log?page='+syncPage);if(token!==syncToken||!A.user?.admin)return;$('#sync-content').innerHTML=renderSyncHealth(data.health)+(data.freshness?`<section class="analytics-box"><h3>${data.freshness.overdue?'A successful sync is overdue':'Sync schedule'}</h3><p class="analytics-caption">Discovery, due demo checks and screenshot batches are requested every two hours. GitHub may delay or skip triggers. ${data.freshness.lastSuccessAt?'Last successful sync: '+esc(new Date(data.freshness.lastSuccessAt).toLocaleString())+'.':'No successful sync appears in the current workflow history.'} ${data.freshness.overdue?'More than three hours have passed since the last successful run. Review the latest workflow and its publication steps.':''}</p></section>`:'')+(data.notice?`<p class="analytics-caption">${esc(data.notice)}</p>`:'')+(data.runs.length?data.runs.map(run=>`<article class="analytics-box sync-run"><div class="panel-heading"><div><h3>${esc(new Date(run.startedAt).toLocaleString())}</h3><p class="small">${esc(run.trigger)} · Run ${esc(run.id)}${run.attempt>1?' · Attempt '+Number(run.attempt):''}</p></div><span class="status-pill">${esc(run.status.replaceAll('_',' '))}</span></div>${run.diagnostics?`<p class="analytics-caption">${esc(run.diagnostics.message)}</p>`:''}${run.counts?`<div class="metric-grid">${metric(run.counts.added,'Records added')}${metric(run.counts.updated,'Records updated')}${metric(run.counts.after,'Total records')}${metric(run.counts.withDemo??null,'With demo page')}${metric(run.temporaryFailures,'Reported failures / retries')}</div><p class="small">${Number(run.counts.before).toLocaleString()} before this run · ${Number(run.counts.removed).toLocaleString()} removed or merged</p><p class="small">${run.counts.withDemo==null?'Demo-page counts were not recorded for this run.':'With demo page counts available listings with usable demo links after this sync. It does not guarantee every demo feature works.'}</p>`:`<p class="analytics-caption">${run.diagnostics?.kind==='cancelled_before_start'?'No records were scanned in this run.':'Record-change counts were not recorded for this run.'}</p>`}${run.finishedAt?`<p class="small">Finished ${esc(new Date(run.finishedAt).toLocaleString())}</p>`:''}${run.stages?.length?`<details><summary>Stage results</summary><div class="help-table-wrap"><table class="analytics-table"><thead><tr><th>Stage</th><th>Result</th><th>Reported failures / retries</th><th>Warnings</th><th>Unavailable</th><th>Inconclusive</th></tr></thead><tbody>${run.stages.map(stage=>`<tr><td>${esc(stage.name)}</td><td>${esc(stage.status)}</td><td>${Number(stage.temporaryFailures||0)}</td><td>${Number(stage.warnings||0)}</td><td>${Number(stage.unavailableResponses||0)}</td><td>${Number(stage.inconclusiveChecks||0)}</td></tr>`).join('')}</tbody></table></div></details>`:''}<p><a href="${esc(run.url)}" target="_blank" rel="noopener">View full workflow log ↗</a></p></article>`).join(''):'<p class="chart-empty">No sync runs are available yet.</p>');$('#sync-prev').hidden=syncPage===1;$('#sync-next').hidden=!data.hasMore}catch(e){if(token===syncToken&&A.user?.admin)$('#sync-content').innerHTML=`<p class="loading-note">${esc(e.message)}</p>`;if(e.status===401||e.status===403)await A.refresh()}}
function renderSyncHealth(health){if(!health)return '';const alerts=health.alerts||[];return `<section class="analytics-box sync-health"><div class="panel-heading"><h3>${health.state==='healthy'?'Syncs are up to date':health.state==='unknown'?'Sync status needs checking':'Syncs need attention'}</h3><span class="status-pill">${alerts.length?alerts.length+' notice'+(alerts.length===1?'':'s'):'No active alerts'}</span></div>${alerts.map(a=>`<article class="sync-alert ${a.level==='error'?'error':''}" role="status"><h4>${esc(a.title)}</h4><p>${esc(a.message)}</p><a href="${esc(a.url)}" target="_blank" rel="noopener">Inspect workflow ↗</a></article>`).join('')}<details class="sync-recovery"><summary>Run a sync or retry safely</summary><ol><li>Open <a href="${esc(health.workflowUrl)}" target="_blank" rel="noopener">GitHub Actions ↗</a> and check that no catalogue sync is already running or queued.</li><li>For a failed run, inspect its log. Fix configuration or permissions before retrying those errors. Temporary source failures normally retry automatically.</li><li>Use <strong>Run workflow</strong> on the <strong>main</strong> branch for a fresh scan. Enable <strong>Refresh demo health and screenshots now</strong> only when an immediate browser batch is needed.</li><li>Return here and refresh. Check publication succeeded before treating scanned additions as live.</li></ol><p class="analytics-caption">These alerts appear in the admin dashboard; email and push notifications are not configured. Checked ${esc(new Date(health.checkedAt).toLocaleString())}.</p></details></section>`}
setInterval(()=>{if(A.user?.admin&&activeTab==='sync'&&!document.hidden&&syncPage===1)void loadSyncLog()},60000);
$('#refresh-sync').onclick=()=>void loadSyncLog();$('#sync-prev').onclick=()=>{syncPage=Math.max(1,syncPage-1);void loadSyncLog()};$('#sync-next').onclick=()=>{syncPage++;void loadSyncLog()};

gate();
